class Solution {
public:
    long long countSubarrays(vector<int>& nums, int minK, int maxK) {
        long long ans = 0;
        long long run = 0;
        for (int x : nums) {
            if (x >= minK && x <= maxK) {
                run++;
            } else {
                ans += run * (run + 1) / 2;
                run = 0;
            }
        }
        ans += run * (run + 1) / 2;
        return ans;
    }
};
